B.baU=new A.a("\u064a\u0639\u0646\u064a \u0644\u0648 \u0623\u0646 \u0647\u0646\u0627\u0643 \u0642\u0631\u0622\u0646\u0627 \u0628\u0647\u0630\u0647 \u0627\u0644\u0645\u062b\u0627\u0628\u0629 \u0644\u0643\u0627\u0646 \u0647\u0630\u0627 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645\u060c \u0641\u0647\u0648 \u0644\u064a\u0633 \u0644\u0647 \u0645\u062b\u064a\u0644 \u0644\u0627 \u0645\u0646 \u0642\u0628\u0644 \u0648\u0644\u0627 \u0645\u0646 \u0628\u0639\u062f\u060c \u062c\u0648\u0627\u0628 \u0644\u0648 \u0645\u062d\u0630\u0648\u0641 \u062f\u0644 \u0639\u0644\u064a\u0647 \u0627\u0644\u0645\u0642\u0627\u0645.",null)
B.aLG=new A.a("\u0644\u0642\u062f \u0643\u0627\u0646 \u0647\u062f\u0641 \u0632\u0639\u0645\u0627\u0621 \u0642\u0631\u064a\u0634 \u0645\u0646 \u062a\u0644\u0643 \u0627\u0644\u0645\u0637\u0627\u0644\u0628\u060c \u0647\u0648 \u0634\u0646 \u062d\u0631\u0628 \u0625\u0639\u0644\u0627\u0645\u064a\u0629 \u0636\u062f \u0627\u0644\u062f\u0639\u0648\u0629 \u0648\u0627\u0644\u062f\u0627\u0639\u064a\u0629\u060c \u0648\u0627\u0644\u062a\u0622\u0645\u0631 \u0639\u0644\u0649 \u0627\u0644\u062d\u0642\u060c \u0643\u064a \u062a\u0628\u062a\u0639\u062f \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0639\u0646\u0647 \ufdfa \u0644\u0623\u0646\u0647\u0645 \u064a\u0637\u0627\u0644\u0628\u0648\u0646 \u0628\u0623\u0645\u0648\u0631 \u064a\u062f\u0631\u0643\u0648\u0646 \u0623\u0646\u0647\u0627 \u0644\u064a\u0633\u062a \u0637\u0628\u064a\u0639\u0629 \u0647\u0630\u0647 \u0627\u0644\u062f\u0639\u0648\u0629\u061b \u0648\u0644\u0647\u0630\u0627 \u0623\u0635\u0631\u0648\u0627 \u0639\u0644\u064a\u0647\u0627\u060c \u0628\u0644 \u0644\u0642\u062f \u0635\u0631\u062d\u0648\u0627 \u0628\u0623\u0646 \u0644\u0648 \u062a\u062d\u0642\u0642 \u0634\u064a\u0621 \u0645\u0646 \u0630\u0644\u0643 \u0641\u0644\u0646 \u064a\u0624\u0645\u0646\u0648\u0627 \u0623\u064a\u0636\u0627 \u0628\u0647\u0630\u0647 \u0627\u0644\u062f\u0639\u0648\u0629\u060c \u0648\u0647\u0630\u0627 \u0643\u0644\u0647 \u0645\u062d\u0627\u0648\u0644\u0629 \u0645\u0646\u0647\u0645 \u0644\u0625\u0638\u0647\u0627\u0631 \u0639\u062c\u0632 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0648\u0627\u062a\u062e\u0627\u0630 \u0630\u0644\u0643 \u0630\u0631\u064a\u0639\u0629 \u0644\u0645\u0646\u0639 \u0627\u0644\u0646\u0627\u0633 \u0639\u0646 \u0627\u062a\u0628\u0627\u0639\u0647.",null)
