B.aJQ=new A.a("\u0623\u0648\u0644\u0645 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0641\u064a \u0639\u0631\u0633 \u0632\u064a\u0646\u0628 \u0648\u0644\u064a\u0645\u0629 \u0643\u0628\u064a\u0631\u0629\u060c \u0641\u0623\u0648\u0644\u0645 \u0628\u0634\u0627\u0629 \u0648\u0642\u062f \u062f\u0639\u0649 \u0625\u0644\u0649 \u0627\u0644\u0648\u0644\u064a\u0645\u0629 \u0643\u0644 \u0645\u0646 \u0644\u0642\u064a\u0647 \u0623\u0646\u0633 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0628\u0646\u0627\u0621\u064b \u0639\u0644\u0649 \u0623\u0645\u0631 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u060c \u0641\u0639\u0646 \u0623\u0646\u0633 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0642\u0627\u0644: \u0645\u0627 \u0631\u0623\u064a\u062a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0623\u0648\u0644\u0645 \u0639\u0644\u0649 \u0627\u0645\u0631\u0623\u0629 \u0645\u0646 \u0646\u0633\u0627\u0626\u0647 \u0645\u0627 \u0623\u0648\u0644\u0645 \u0639\u0644\u0649 \u0632\u064a\u0646\u0628\u060c \u0641\u0625\u0646\u0647 \u0630\u0628\u062d \u0634\u0627\u0629.",null)
B.aFK=new A.a("\u0641\u0639\u0646 \u0623\u0646\u0633 \u0628\u0646 \u0645\u0627\u0644\u0643 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0642\u0627\u0644: \u062a\u0632\u0648\u062c \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u062f\u062e\u0644 \u0628\u0623\u0647\u0644\u0647\u060c \u0642\u0627\u0644: \u0641\u0635\u0646\u0639\u062a \u0623\u0645\u064a \u0623\u0645 \u0633\u0644\u064a\u0645 \u062d\u064a\u0633\u0627\u064b \u0641\u062c\u0639\u0644\u062a\u0647 \u0641\u064a \u062a\u0648\u0631 -\u0625\u0646\u0627\u0621- \u0641\u0642\u0627\u0644\u062a: \u064a\u0627 \u0623\u0646\u0633: \u0627\u0630\u0647\u0628 \u0628\u0647\u0630\u0627 \u0625\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0642\u0644: \u0628\u0639\u062b\u062a \u0628\u0647\u0630\u0627 \u0625\u0644\u064a\u0643 \u0623\u0645\u064a\u060c \u0648\u0647\u064a \u062a\u0642\u0631\u0626\u0643 \u0627\u0644\u0633\u0644\u0627\u0645 \u0648\u062a\u0642\u0648\u0644: \u0625\u0646 \u0647\u0630\u0627 \u0644\u0643 \u0645\u0646\u0627 \u0642\u0644\u064a\u0644 \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647! \u0642\u0627\u0644: \u0641\u0630\u0647\u0628\u062a \u0628\u0647\u0627 \u0625\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u060c \u0641\u0642\u0644\u062a: \u0625\u0646 \u0623\u0645\u064a \u062a\u0642\u0631\u0626\u0643 \u0627\u0644\u0633\u0644\u0627\u0645 \u0648\u062a\u0642\u0648\u0644: \u0625\u0646 \u0647\u0630\u0627 \u0644\u0643 \u0645\u0646\u0627 \u0642\u0644\u064a\u0644 \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647! \u0641\u0642\u0627\u0644: \u0636\u0639\u0647 \u062b\u0645 \u0642\u0627\u0644: \u0627\u0630\u0647\u0628 \u0641\u0627\u062f\u0639 \u0644\u064a \u0641\u0644\u0627\u0646\u0627\u064b \u0648\u0641\u0644\u0627\u0646\u0627\u064b\u060c \u0648\u0645\u0646 \u0644\u0642\u064a\u062a\u060c \u0648\u0633\u0645\u0649 \u0631\u062c\u0627\u0644\u0627\u064b\u060c \u0642\u0627\u0644: \u0641\u062f\u0639\u0648\u062a \u0645\u0646 \u0633\u0645\u0649 \u0648\u0645\u0646 \u0644\u0642\u064a\u062a\u060c \u0642\u0627\u0644: \u0642\u0644\u062a \u0644\u0623\u0646\u0633: \u0639\u062f\u062f \u0643\u0645 \u0643\u0627\u0646\u0648\u0627\u061f \u0642\u0627\u0644: \u0632\u0647\u0627\u0621 \u062b\u0644\u0627\u062b\u0645\u0627\u0626\u0629 \u0648\u0642\u0627\u0644 \u0644\u064a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u064a\u0627\u0623\u0646\u0633: \u0647\u0627\u062a \u0627\u0644\u062a\u0648\u0631\u060c \u0642\u0627\u0644: \u0641\u062f\u062e\u0644\u0648\u0627 \u062d\u062a\u0649 \u0627\u0645\u062a\u0644\u0623\u062a \u0627\u0644\u0635\u0641\u0629 \u0648\u0627\u0644\u062d\u062c\u0631\u0629\u060c \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u0644\u064a\u062a\u062d\u0644\u0642 \u0639\u0634\u0631\u0629 \u0639\u0634\u0631\u0629\u060c \u0648\u0644\u064a\u0623\u0643\u0644 \u0643\u0644 \u0625\u0646\u0633\u0627\u0646 \u0645\u0645\u0627 \u064a\u0644\u064a\u0647\u060c \u0642\u0627\u0644: \u0641\u0623\u0643\u0644\u0648\u0627 \u062d\u062a\u0649 \u0634\u0628\u0639\u0648\u0627.",null)
