B.aHN=new A.a("\u0644\u0642\u062f \u0645\u0627\u0631\u0633 \u0639\u0631\u0648\u0629 \u0628\u0646 \u0645\u0633\u0639\u0648\u062f \u0641\u064a \u0645\u0641\u0627\u0648\u0636\u0627\u062a\u0647 \u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u062d\u0631\u0628 \u0627\u0644\u0646\u0641\u0633\u064a\u0629 \u0645\u0646 \u0625\u0634\u0627\u0639\u0629 \u0648\u0627\u0641\u062a\u0639\u0627\u0644 \u0627\u0644\u0623\u0632\u0645\u0627\u062a \u0648\u0625\u062b\u0627\u0631\u0629 \u0627\u0644\u0631\u0639\u0628 \u0625\u0644\u0627 \u0623\u0646 \u062a\u0644\u0643 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u062a\u062d\u0637\u0645\u062a \u0623\u0645\u0627\u0645 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0627\u0644\u0639\u0645\u064a\u0642 \u0648\u0627\u0644\u062a\u0643\u0648\u064a\u0646 \u0627\u0644\u062f\u0642\u064a\u0642 \u0648\u0627\u0644\u0635\u0641 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064a \u0627\u0644\u0645\u0631\u0635\u0648\u0635 \u0648\u0645\u0646 \u0627\u0644\u0645\u0641\u0627\u0631\u0642\u0627\u062a \u0627\u0644\u0631\u0627\u0626\u0639\u0629 \u0627\u0644\u062a\u064a \u062d\u0635\u0644\u062a \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0645\u0641\u0627\u0648\u0636\u0627\u062a \u0645\u0639 \u0639\u0631\u0648\u0629 \u0628\u0646 \u0645\u0633\u0639\u0648\u062f \u0648\u0647\u064a \u0645\u0646 \u0639\u062c\u0627\u0626\u0628 \u0627\u0644\u0623\u062d\u062f\u0627\u062b \u0627\u0644\u062a\u064a \u064a\u0633\u062a\u0634\u0641 \u0645\u0646\u0647\u0627 \u0627\u0644\u062f\u0644\u064a\u0644 \u0627\u0644\u0642\u0627\u0637\u0639 \u0639\u0644\u0649 \u0642\u0648\u0629 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0627\u0644\u062a\u064a \u0643\u0627\u0646\u062a \u064a\u062a\u0645\u062a\u0639 \u0628\u0647\u0627 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0646\u0628\u064a \ufdfa \u060c \u0648\u0639\u0644\u0649 \u0642\u062f\u0631\u0629 \u0647\u0630\u0627 \u0627\u0644\u062f\u064a\u0646 \u0645\u0646 \u062a\u062d\u0648\u064a\u0644 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0645\u0646 \u0634\u064a\u0637\u0627\u0646 \u0645\u0631\u064a\u062f \u0625\u0644\u0649 \u0625\u0646\u0633\u0627\u0646 \u0641\u0627\u0636\u0644 \u0646\u0628\u064a\u0644 \u062d\u064a\u062b \u0643\u0627\u0646 \u0623\u062d\u062f \u0627\u0644\u0630\u064a\u0646 \u064a\u062a\u0648\u0644\u0648\u0646 \u062d\u0631\u0627\u0633\u0629 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0623\u062b\u0646\u0627\u0621 \u0645\u062d\u0627\u062f\u062b\u0627\u062a\u0647 \u0645\u0639 \u0639\u0631\u0648\u0629 \u0628\u0646 \u0645\u0633\u0639\u0648\u062f \u0627\u0644\u062b\u0642\u0641\u064a \u0641\u064a \u0627\u0644\u062d\u062f\u064a\u0628\u064a\u0629 \u0647\u0648 \u0627\u0644\u0645\u063a\u064a\u0631\u0629 \u0628\u0646 \u0634\u0639\u0628\u0629\u060c \u0627\u0628\u0646 \u0623\u062e \u0639\u0631\u0648\u0629 \u0628\u0646 \u0645\u0633\u0639\u0648\u062f \u0646\u0641\u0633\u0647\u060c \u0648\u0643\u0627\u0646 \u0627\u0644\u0645\u063a\u064a\u0631\u0629 \u0647\u0630\u0627 \u0642\u0628\u0644 \u0623\u0646 \u064a\u0647\u062f\u064a\u0647 \u0627\u0644\u0644\u0647 \u0644\u0644\u0625\u0633\u0644\u0627\u0645 \u0634\u0627\u0628\u0627\u064b \u0641\u0627\u062a\u0643\u0627\u064b \u0633\u0643\u064a\u0631\u0627\u064b \u0642\u0627\u0637\u0639\u0627\u064b \u0644\u0644\u0637\u0631\u064a\u0642\u060c \u063a\u064a\u0631 \u0623\u0646 \u062f\u062e\u0648\u0644\u0647 \u0644\u0644\u0625\u0633\u0644\u0627\u0645 \u062d\u0648\u0644\u0647 \u0625\u0644\u0649 \u0625\u0646\u0633\u0627\u0646 \u0622\u062e\u0631 \u0648\u0642\u062f \u0623\u0635\u0628\u062d \u0628\u0641\u0636\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0645\u0646 \u0627\u0644\u0635\u0641\u0648\u0629 \u0627\u0644\u0645\u0624\u0645\u0646\u0629\u060c \u0648\u0642\u062f \u0648\u0642\u0639 \u0639\u0644\u064a\u0647 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631 \u0644\u064a\u0642\u0648\u0645 \u0628\u0645\u0647\u0627\u0645 \u062d\u0631\u0627\u0633\u0629 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0641\u064a \u0630\u0644\u0643 \u0627\u0644\u062c\u0648 \u0627\u0644\u0645\u0644\u0628\u062f \u0628\u063a\u064a\u0648\u0645 \u0627\u0644\u062d\u0631\u0628\u060c \u0648\u0643\u0627\u0646 \u0645\u0646 \u0639\u0627\u062f\u0629 \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629 \u0641\u064a \u0627\u0644\u0645\u0641\u0627\u0648\u0636\u0627\u062a\u060c \u0623\u0646 \u064a\u0645\u0633\u0643 \u0627\u0644\u0645\u0641\u0627\u0648\u0636 \u0628\u0644\u062d\u064a\u0629 \u0627\u0644\u0630\u064a \u064a\u0631\u0627\u0647 \u0646\u062f\u0627\u064b \u0644\u0647 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062d\u062f\u064a\u062b\u060c \u0648\u0639\u0644\u0649 \u0647\u0630\u0647 \u0627\u0644\u0642\u0627\u0639\u062f\u0629 \u0643\u0627\u0646 \u0639\u0631\u0648\u0629 \u0628\u0646 \u0645\u0633\u0639\u0648\u062f \u064a\u0645\u0633\u0643 \u0628\u0644\u062d\u064a\u0629 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0642\u0634\u0629\u060c \u0627\u0644\u0623\u0645\u0631 \u0627\u0644\u0630\u064a \u0623\u063a\u0636\u0628 \u0627\u0644\u0645\u063a\u064a\u0631\u0629 \u0628\u0646 \u0634\u0639\u0628\u0629 \u0627\u0644\u0630\u064a \u0643\u0627\u0646 \u0642\u0627\u0626\u0645\u0627\u064b \u0639\u0644\u0649 \u0631\u0623\u0633 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0628\u0627\u0644\u0633\u064a\u0641 \u064a\u062d\u0631\u0633\u0647 \u0648\u0639\u0644\u0649 \u0648\u062c\u0647\u0647 \u0627\u0644\u0645\u063a\u0641\u0631 \u0641\u0627\u0646\u062a\u0647\u0631 \u0639\u0645\u0647 \u0648\u0642\u0631\u0639 \u064a\u062f\u0647 \u0628\u0642\u0627\u0626\u0645 \u0627\u0644\u0633\u064a\u0641 \u0642\u0627\u0626\u0644\u0627\u064b \u0644\u0647: \u0623\u0643\u0641\u0641 \u064a\u062f\u0643 \u0639\u0646 \u0645\u0633 \u0644\u062d\u064a\u0629 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0642\u0628\u0644 \u0623\u0646 \u0644\u0627 \u062a\u0635\u0644 \u0625\u0644\u064a\u0643.",null)
B.aI6=new A.a("\u0648\u0643\u0627\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u064a\u0628\u062a\u0633\u0645 \u0644\u0644\u0630\u064a \u064a\u062c\u0631\u064a \u0628\u064a\u0646 \u0639\u0631\u0648\u0629 \u0627\u0644\u0645\u0634\u0631\u0643 \u0648\u0628\u064a\u0646 \u0627\u0628\u0646 \u0623\u062e\u064a\u0647 \u0627\u0644\u0645\u0624\u0645\u0646\u060c \u0648\u0644\u0645\u0627 \u0643\u0627\u0646 \u0627\u0644\u0645\u063a\u064a\u0631\u0629 \u0628\u0646 \u0634\u0639\u0628\u0629 \u064a\u0642\u0641 \u0628\u0644\u0628\u0627\u0633\u0647 \u0627\u0644\u062d\u0631\u0628\u064a \u0645\u062a\u0648\u0634\u062d\u0627\u064b \u0628\u0633\u064a\u0641\u0647 \u0648\u062f\u0631\u0639\u0647 \u0648\u0639\u0644\u0649 \u0648\u062c\u0647\u0647 \u0627\u0644\u0645\u063a\u0641\u0631\u060c \u0641\u0625\u0646 \u0639\u0645\u0647 \u0639\u0631\u0648\u0629 \u0644\u0645 \u064a\u0643\u0646 \u0628\u0627\u0633\u062a\u0637\u0627\u0639\u062a\u0647 \u0645\u0639\u0631\u0641\u062a\u0647\u060c \u0641\u0642\u0627\u0644 \u0644\u0644\u0646\u0628\u064a \ufdfa \u0648\u0647\u0648 \u0641\u064a \u0623\u0634\u062f \u0627\u0644\u063a\u0636\u0628: \u0644\u064a\u062a \u0634\u0639\u0631\u064a \u0645\u0646 \u0623\u0646\u062a \u064a\u0627\u0645\u062d\u0645\u062f \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u0630\u064a \u0623\u0631\u0649 \u0645\u0646 \u0628\u064a\u0646 \u0623\u0635\u062d\u0627\u0628\u0643\u061f \u0641\u0642\u0627\u0644 \u0644\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u0647\u0630\u0627 \u0627\u0628\u0646 \u0623\u062e\u064a\u0643 \u0627\u0644\u0645\u063a\u064a\u0631\u0629 \u0628\u0646 \u0634\u0639\u0628\u0629\u060c \u0641\u0642\u0627\u0644 \u0644\u0647 \u0639\u0645\u0647: \u0648\u0623\u0646\u062a \u0628\u0630\u0644\u0643 \u064a\u0627\u063a\u062f\u0631\u061f \u0644\u0642\u062f \u0623\u0648\u0631\u062b\u062a\u0646\u0627 \u0627\u0644\u0639\u062f\u0627\u0648\u0629 \u0645\u0646 \u062b\u0642\u064a\u0641 \u0623\u0628\u062f \u0627\u0644\u062f\u0647\u0631\u060c \u0648\u0627\u0644\u0644\u0647 \u0645\u0627\u063a\u0633\u0644\u062a \u063a\u062f\u0631\u062a\u0643 \u0625\u0644\u0627 \u0628\u0627\u0644\u0623\u0645\u0633 \u0643\u0627\u0646 \u0627\u0644\u0645\u063a\u064a\u0631\u0629 \u0635\u062d\u0628 \u0642\u0648\u0645\u0627\u064b \u0641\u064a \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629 \u0641\u0642\u062a\u0644\u0647\u0645 \u0648\u0623\u062e\u0630 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u062b\u0645 \u062c\u0627\u0621 \u0641\u0623\u0633\u0644\u0645 \u0641\u0642\u0627\u0644 \u0627\u0644\u0646\u0628\u064a \ufdfa : \u0623\u0645\u0627 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0641\u0623\u0642\u0628\u0644 \u0648\u0623\u0645\u0627 \u0627\u0644\u0645\u0627\u0644 \u0641\u0644\u0633\u062a \u0645\u0646\u0647 \u0641\u064a \u0634\u064a\u0621.",null)
