B.b35=new A.a("\u0648\u0643\u0627\u0646 \u0627\u0644\u0623\u0648\u0633 \u0648\u0627\u0644\u062e\u0632\u0631\u062c \u0645\u0646 \u0642\u062d\u0637\u0627\u0646\u060c \u0648\u0627\u0644\u0645\u0647\u0627\u062c\u0631\u0648\u0646 \u0648\u0645\u0646 \u0633\u0628\u0642 \u0625\u0644\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0641\u064a \u0645\u0643\u0629 \u0648\u0645\u0627 \u062d\u0648\u0644\u0647\u0627 \u0645\u0646 \u0639\u062f\u0646\u0627\u0646\u060c \u0648\u0644\u0645\u0627 \u0647\u0627\u062c\u0631 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u0648\u0642\u0627\u0645 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0628\u0646\u0635\u0631\u0647\u060c \u0627\u062c\u062a\u0645\u0639\u062a \u0628\u0630\u0644\u0643 \u0639\u062f\u0646\u0627\u0646 \u0648\u0642\u062d\u0637\u0627\u0646 \u062a\u062d\u062a \u0644\u0648\u0627\u0621 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u0643\u0627\u0646\u0648\u0627 \u0643\u062c\u0633\u062f\u064d \u0648\u0627\u062d\u062f\u0650\u060c \u0648\u0643\u0627\u0646\u062a \u0628\u064a\u0646\u0647\u0645\u0627 \u0645\u0641\u0627\u0636\u0644\u0629 \u0648\u0645\u0633\u0627\u0628\u0642\u0629 \u0641\u064a \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629.",null)
B.b3L=new A.a("\u0648\u0628\u0630\u0644\u0643 \u0644\u0645 \u064a\u062c\u062f \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0633\u0628\u064a\u0644\u0627\u064b \u0625\u0644\u0649 \u0642\u0644\u0648\u0628\u0647\u0645 \u0644\u0625\u062b\u0627\u0631\u0629 \u0627\u0644\u0641\u062a\u0646\u0629 \u0648\u0627\u0644\u062a\u0639\u0632\u064a \u0628\u0639\u0632\u0627\u0621 \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629\u060c \u0628\u0627\u0633\u0645 \u0627\u0644\u062d\u0645\u064a\u0629 \u0627\u0644\u0642\u062d\u0637\u0627\u0646\u064a\u0629 \u0623\u0648 \u0627\u0644\u0639\u062f\u0646\u0627\u0646\u064a\u0629\u060c \u0641\u0643\u0627\u0646\u062a \u0644\u0643\u0644 \u0630\u0644\u0643 \u0645\u062f\u064a\u0646\u0629 \u064a\u062b\u0631\u0628 \u0623\u0635\u0644\u062d \u0645\u0643\u0627\u0646 \u0644\u0647\u062c\u0631\u0629 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0648\u0623\u0635\u062d\u0627\u0628\u0647 \u0648\u0627\u062a\u062e\u0627\u0630\u0647\u0645 \u0644\u0647\u0627 \u062f\u0627\u0631\u0627\u064b \u0648\u0642\u0631\u0627\u0631\u0627\u064b\u060c \u062d\u062a\u0649 \u064a\u0642\u0648\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u064a\u0634\u0642 \u0637\u0631\u064a\u0642\u0647 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645\u060c \u0648\u064a\u0641\u062a\u062d \u0627\u0644\u062c\u0632\u064a\u0631\u0629 \u062b\u0645 \u064a\u0641\u062a\u062d \u0627\u0644\u0639\u0627\u0644\u0645 \u0627\u0644\u0645\u062a\u0645\u062f\u0646.",null)
