B.aMN=new A.a("\u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u062f\u0639\u0627\u0626\u0647 \u0639\u0646\u062f\u0645\u0627 \u0642\u0627\u0644: \u0627\u0644\u0644\u0647\u0645 \u0641\u0625\u0646 \u0628\u0642\u064a \u0645\u0646 \u062d\u0631\u0628 \u0642\u0631\u064a\u0634 \u0634\u064a\u0621 \u0641\u0623\u0628\u0642\u0646\u064a \u0644\u0647 \u062d\u062a\u0649 \u0623\u062c\u0627\u0647\u062f\u0647\u0645 \u0641\u064a\u0643 \u0648\u0642\u062f \u0627\u0633\u062a\u062c\u064a\u0628 \u062f\u0639\u0627\u0624\u0647 \u0641\u062a\u062d\u062c\u0631 \u062c\u0631\u062d\u0647 \u0648\u062a\u0645\u0627\u062b\u0644 \u0644\u0644\u0634\u0641\u0627\u0621 \u062d\u062a\u0649 \u0643\u0627\u0646\u062a \u063a\u0632\u0648\u0629 \u0628\u0646\u064a \u0642\u0631\u064a\u0638\u0629\u060c \u0648\u062c\u0639\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0627\u0644\u062d\u0643\u0645 \u0641\u064a\u0647\u0645 \u0625\u0644\u064a\u0647\u060c \u0641\u062d\u0643\u0645 \u0641\u064a\u0647\u0645 \u0628\u0627\u0644\u062d\u0642 \u0648\u0644\u0645 \u062a\u062e\u0630\u0647 \u0641\u064a \u0627\u0644\u0644\u0647 \u0644\u0648\u0645\u0629 \u0644\u0627\u0626\u0645 \u0648\u0647\u0630\u0627 \u062f\u0644\u064a\u0644 \u0639\u0644\u0649 \u062a\u062c\u0631\u062f \u0642\u0644\u0628\u0647 \u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649.",null)
B.aTO=new A.a("\u0648\u0645\u0646 \u0625\u0643\u0631\u0627\u0645 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0642\u0648\u0644\u0647 \u0644\u0644\u0623\u0646\u0635\u0627\u0631 \u0639\u0646\u062f\u0645\u0627 \u062c\u0627\u0621 \u0633\u0639\u062f \u0644\u0644\u062d\u0643\u0645 \u0641\u064a \u0628\u0646\u064a \u0642\u0631\u064a\u0638\u0629: \u0642\u0648\u0645\u0648\u0627 \u0625\u0644\u0649 \u0633\u064a\u062f\u0643\u0645.",null)
B.aWf=new A.a("\u0648\u0639\u0646\u062f\u0645\u0627 \u0646\u0641\u0630 \u062d\u0643\u0645 \u0627\u0644\u0644\u0647 \u0641\u064a \u064a\u0647\u0648\u062f \u0628\u0646\u064a \u0642\u0631\u064a\u0638\u0629 \u0631\u0641\u0639 \u0633\u0639\u062f \u064a\u062f\u0647 \u064a\u062f\u0639\u0648 \u0627\u0644\u0644\u0647 \u062b\u0627\u0646\u064a\u0629 \u064a\u0642\u0648\u0644: \u0627\u0644\u0644\u0647\u0645 \u0641\u0625\u0646\u064a \u0623\u0638\u0646 \u0623\u0646\u0643 \u0642\u062f \u0648\u0636\u0639\u062a \u0627\u0644\u062d\u0631\u0628 \u0628\u064a\u0646\u0646\u0627 \u0648\u0628\u064a\u0646\u0647\u0645 \u064a\u0639\u0646\u064a \u0642\u0631\u064a\u0634\u0627\u064b \u0648\u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0641\u0625\u0646 \u0643\u0646\u062a \u0642\u062f \u0648\u0636\u0639\u062a \u0627\u0644\u062d\u0631\u0628 \u0628\u064a\u0646\u0646\u0627 \u0648\u0628\u064a\u0646\u0647\u0645 \u0641\u0627\u0641\u062c\u0631\u0648\u0647\u0627 \u0648\u0627\u062c\u0639\u0644 \u0645\u0648\u062a\u064a \u0641\u064a\u0647\u0627\u060c \u0648\u0642\u062f \u0627\u0633\u062a\u062c\u064a\u0628 \u062f\u0639\u0627\u0624\u0647 \u0641\u0627\u0646\u0641\u062c\u0631 \u062c\u0631\u062d\u0647 \u062a\u0644\u0643 \u0627\u0644\u0644\u064a\u0644\u0629 \u0648\u0645\u0627\u062a \u0631\u062d\u0645\u0647 \u0627\u0644\u0644\u0647.",null)
